{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.fact_grn_issues_rfid AS WITH grn_base AS ( SELECT UNIQUEKEY, ORIGIN, ORDER_DATE, EDD, ORDER_NUMBER, SUPPLIER_ORDER_NO, TRANSFER_BRANCH_CODE, TO_PARTY AS BRANCH_NAME, FROM_PARTY AS VENDOR_GRN, PARTY_USER_CODE, BRANCH_SHORT_NAME, CAST(VOUCH_CODE AS VARCHAR) AS GRN_NUMBER, ORDER_PREFIX, ACTION_CODE, NET_ORDER_AMOUNT, ORDER_AMOUNT, TOTAL_TAX, AGENT_NAME, LOGIC_USER_CODE, LOT_NUMBER, PO_MRP, PENDING_QTY, TOTAL_QTY, TXN_CODE, DATE_TRUNC(\'WEEK\', ORDER_DATE)::DATE AS WEEK_START_DATE, CASE WHEN COALESCE(TOTAL_QTY, 0) = COALESCE(PENDING_QTY, 0) THEN \'GRN Pending\' ELSE \'GRN Done\' END AS GRN_STATUS FROM snitch_db.maplemonk.logic_purchase_order ), issue_base AS ( SELECT ID AS ISSUE_ID, CREATED_AT_DATE, UPDATED_AT_DATE, QTY AS ISSUE_QTY, SKU, \"Issue\" AS ISSUE, SUB_ISSUE, VENDOR AS VENDOR_ISSUE, COMMENTS, PO_NUMBER, INVOICE_NUMBER, CREATED_AT AS ISSUE_CREATED_AT, CREATED_BY, LAST_UPDATED_AT FROM snitch_db.maplemonk.issues_factory_sorted ), rfid_base AS ( SELECT CAST(\"Doc No\" AS VARCHAR) AS GRN_NUMBER, CASE WHEN LOWER(\"Matching Status\") = \'pending\' THEN \'NON RFID\' ELSE \'RFID\' END AS RFID_STATUS FROM snitch_db.maplemonk.s3_rfid_inward ) SELECT g.UNIQUEKEY, g.ORIGIN, g.ORDER_DATE, g.EDD, g.ORDER_NUMBER, g.SUPPLIER_ORDER_NO, g.TRANSFER_BRANCH_CODE, g.BRANCH_NAME, g.BRANCH_SHORT_NAME, g.VENDOR_GRN, g.PARTY_USER_CODE, g.GRN_NUMBER, g.ORDER_PREFIX, g.LOT_NUMBER AS PO_NUMBER_GRN, g.NET_ORDER_AMOUNT, g.ORDER_AMOUNT, g.TOTAL_TAX, g.AGENT_NAME, g.LOGIC_USER_CODE, g.PO_MRP, g.PENDING_QTY, g.TOTAL_QTY, g.TXN_CODE, g.WEEK_START_DATE, g.GRN_STATUS, COALESCE(r.RFID_STATUS, \'NON RFID\') AS RFID_STATUS, i.ISSUE_ID, i.CREATED_AT_DATE AS ISSUE_CREATED_AT_DATE, i.UPDATED_AT_DATE AS ISSUE_UPDATED_AT_DATE, i.ISSUE_QTY, i.SKU, i.ISSUE, i.SUB_ISSUE, i.VENDOR_ISSUE, i.COMMENTS, i.PO_NUMBER AS PO_NUMBER_ISSUE, i.INVOICE_NUMBER, i.ISSUE_CREATED_AT, i.CREATED_BY, i.LAST_UPDATED_AT AS ISSUE_LAST_UPDATED_AT, CASE WHEN i.ISSUE_ID IS NULL THEN 0 ELSE 1 END AS HAS_DISCREPANCY FROM grn_base g LEFT JOIN rfid_base r ON r.GRN_NUMBER = g.GRN_NUMBER LEFT JOIN issue_base i ON TRIM(CAST(i.PO_NUMBER AS VARCHAR)) = TRIM(CAST(g.LOT_NUMBER AS VARCHAR));",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            